:root {
  --bg: #14161a;
  --panel: #1c1f26;
  --panel-2: #21252e;
  --line: rgba(255, 255, 255, 0.09);
  --text: #e6e6e6;
  --muted: #9aa4b2;
  --dim: #6b7480;
  --accent: #4d7cfe;
  --accent-soft: rgba(77, 124, 254, 0.14);
  --ok: #3ecf8e;
  --ok-soft: rgba(62, 207, 142, 0.14);
  --warn: #f0b429;
  --error: #ff6b6b;
  --error-soft: rgba(255, 107, 107, 0.12);
  --mono: Consolas, "Courier New", "SFMono-Regular", monospace;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: radial-gradient(circle at 20% 0%, #1e2430 0%, var(--bg) 55%);
  color: var(--text);
  font-family: "Segoe UI", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 13px;
  line-height: 1.6;
  padding: 26px 30px 60px;
  overflow-y: auto;
}
.wrap { max-width: 1020px; margin: 0 auto; }

/* ---------------- 页头 ---------------- */
header { margin-bottom: 22px; }
h1 { margin: 0 0 4px; font-size: 20px; font-weight: 600; letter-spacing: 0.3px; }
.sub { margin: 0; color: var(--muted); font-size: 12.5px; }

/* ---------------- 区块 ---------------- */
section {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 20px;
  margin-bottom: 16px;
}
.sec-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
h2 { margin: 0; font-size: 14px; font-weight: 600; }
.sec-note { color: var(--dim); font-size: 12px; }

/* ---------------- 当前内核卡片 ---------------- */
.current {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 16px;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  margin-bottom: 14px;
}
.ver {
  font-family: var(--mono);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.ver.none { color: var(--dim); font-size: 16px; font-weight: 500; }
.ver-meta { color: var(--muted); font-size: 12px; }
.spacer { flex: 1; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.badge.ok { background: var(--ok-soft); color: var(--ok); }
.badge.bad { background: var(--error-soft); color: var(--error); }
.badge.warn { background: rgba(240, 180, 41, 0.14); color: var(--warn); }
.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 10px 18px;
}
.field { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.field .k { color: var(--dim); flex: none; min-width: 76px; font-size: 12px; }
.field .v {
  font-family: var(--mono);
  font-size: 12.5px;
  color: var(--text);
  word-break: break-all;
  min-width: 0;
}
.field .v.muted { color: var(--muted); font-family: inherit; }

/* ---------------- 表单控件 ---------------- */
select,
input[type="text"],
input[type="number"] {
  background: var(--panel-2);
  border: 1px solid var(--line);
  color: var(--text);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  min-width: 0;
}
select:focus, input:focus { border-color: var(--accent); }
select:disabled, input:disabled { opacity: 0.5; cursor: not-allowed; }
select { max-width: 100%; }
select option { background: #1c1f26; }

button {
  padding: 7px 15px;
  font-size: 12.5px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
}
button:hover:not(:disabled) { background: rgba(255, 255, 255, 0.07); }
button:disabled { opacity: 0.42; cursor: not-allowed; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
button.primary:hover:not(:disabled) { background: #3d6bf5; }
button.danger:hover:not(:disabled) { border-color: var(--error); color: var(--error); }

.row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.row + .row { margin-top: 12px; }
.grow { flex: 1 1 260px; min-width: 0; }
.label { color: var(--muted); font-size: 12px; }

.hint {
  margin-top: 10px;
  font-size: 12px;
  color: var(--muted);
  line-height: 1.75;
}
.hint.err { color: var(--error); }
.hint.ok { color: var(--ok); }

/* ---------------- 限速 ---------------- */
.limit-block {
  padding: 14px 16px;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.limit-block + .limit-block { margin-top: 12px; }
.limit-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.limit-title { font-weight: 600; font-size: 13px; }
.limit-val { font-family: var(--mono); font-size: 12.5px; color: var(--accent); }
.limit-controls { display: flex; align-items: center; gap: 12px; }
input[type="range"] { flex: 1; accent-color: var(--accent); min-width: 120px; }
input[type="number"].small { width: 96px; flex: none; text-align: right; font-family: var(--mono); }

/* ---------------- 进度 ---------------- */
.bar {
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.bar > i {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), #6f4dfe);
  transition: width 0.25s ease;
}
.bar.done > i { background: var(--ok); }
.bar.fail > i { background: var(--error); }

.stages { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.stage {
  padding: 3px 9px;
  border-radius: 6px;
  font-size: 11.5px;
  color: var(--dim);
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
}
.stage.active { color: #fff; border-color: var(--accent); background: var(--accent-soft); }
.stage.done { color: var(--ok); border-color: rgba(62, 207, 142, 0.4); }
.stage.failed { color: var(--error); border-color: rgba(255, 107, 107, 0.5); }

.console {
  margin-top: 12px;
  height: 168px;
  overflow: auto;
  padding: 10px 12px;
  background: #101317;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.65;
  color: #c8d0da;
  white-space: pre-wrap;
  word-break: break-all;
  user-select: text;
}
.console .idle { color: var(--dim); }

.fail-box {
  display: none;
  margin-top: 12px;
  padding: 12px 14px;
  border-radius: 8px;
  background: var(--error-soft);
  border: 1px solid rgba(255, 107, 107, 0.35);
}
.fail-box.show { display: block; }
.fail-title { color: var(--error); font-weight: 600; margin-bottom: 6px; }
.fail-msg { font-family: var(--mono); font-size: 12px; word-break: break-word; }
.fail-safe { margin-top: 8px; color: #ffb4b4; font-size: 12px; }

/* ---------------- 插件表 ---------------- */
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
th { color: var(--dim); font-weight: 500; font-size: 12px; }
td.mono { font-family: var(--mono); font-size: 12px; }
tr:last-child td { border-bottom: none; }
.tag {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--muted);
  margin-right: 6px;
}
.tag.builtin { background: var(--accent-soft); color: #9db8ff; }
.empty { color: var(--dim); padding: 14px 2px; }

/* ---------------- 底部说明 ---------------- */
.notes { color: var(--muted); font-size: 12.5px; }
.notes ul { margin: 8px 0 0; padding-left: 18px; }
.notes li { margin-bottom: 5px; }
.notes code {
  font-family: var(--mono);
  font-size: 11.5px;
  background: rgba(255, 255, 255, 0.06);
  padding: 1px 5px;
  border-radius: 4px;
}

/* ---------------- 骨架 / 加载 / 致命错误 ---------------- */
.sk { display: none; }
.is-loading .sk { display: block; }
.is-loading .real { display: none; }
.sk-bar {
  height: 12px;
  border-radius: 6px;
  background: linear-gradient(90deg, #23272f 25%, #2c313b 37%, #23272f 63%);
  background-size: 400% 100%;
  animation: shimmer 1.3s ease infinite;
  margin-bottom: 8px;
}
.sk-bar.w40 { width: 40%; }
.sk-bar.w70 { width: 70%; }
.sk-bar.w55 { width: 55%; }
@keyframes shimmer {
  0% { background-position: 100% 50%; }
  100% { background-position: 0 50%; }
}

#overlay {
  position: fixed;
  inset: 0;
  background: rgba(20, 22, 26, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
}
#overlay.hidden { display: none; }
.ov-card { width: 420px; text-align: center; padding: 28px; }
.spinner {
  width: 30px;
  height: 30px;
  margin: 0 auto 16px;
  border: 3px solid rgba(255, 255, 255, 0.12);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.9s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.ov-msg { color: var(--muted); font-size: 13px; margin-bottom: 4px; }
.ov-detail {
  margin-top: 12px;
  max-height: 160px;
  overflow: auto;
  text-align: left;
  font-family: var(--mono);
  font-size: 11.5px;
  color: #d5d5d5;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}
.ov-actions { margin-top: 18px; display: flex; gap: 10px; justify-content: center; }
#overlay:not(.error) .ov-actions { display: none; }
#overlay.error .spinner { display: none; }

