'use strict'

/* ------------------------------------------------------------------ *
 * 0. 基础工具
 * ------------------------------------------------------------------ */

var api = window.dshDesktop

function $(id) {
  return document.getElementById(id)
}

/** IPC 抛出的可能是 Error / 带 code 的自定义错误 / 字符串，统一成可读文本。 */
function describeError(err) {
  if (!err) return '未知错误'
  if (typeof err === 'string') return err
  var msg = err.message || String(err)
  if (err.code) msg = '[' + err.code + '] ' + msg
  return msg
}

/** 锁冲突是最常见的失败原因，单独给一句人话解释。 */
function busyHint(msg) {
  if (/UPDATE_BUSY|KERNEL_BUSY|lock|正在(进行|执行)/i.test(msg)) {
    return '（提示：另一个内核任务正在持有更新锁，请等它结束后重试。）'
  }
  return ''
}

function clamp(n, lo, hi) {
  return n < lo ? lo : n > hi ? hi : n
}

function formatBytes(n) {
  var v = Number(n)
  if (!isFinite(v) || v <= 0) return '—'
  var units = ['B', 'KB', 'MB', 'GB']
  var i = 0
  while (v >= 1024 && i < units.length - 1) {
    v = v / 1024
    i++
  }
  return (i === 0 ? String(Math.round(v)) : v.toFixed(1)) + ' ' + units[i]
}

function formatTime(iso) {
  if (!iso) return '—'
  var d = new Date(iso)
  if (isNaN(d.getTime())) return String(iso)
  return d.toLocaleString()
}

var STATUS_LABEL = {
  ready: '可用',
  missing: '缺失',
  broken: '损坏',
  incompatible: '不兼容',
  unknown: '未知'
}

function statusLabel(s) {
  return STATUS_LABEL[s] || s || '未知'
}

/* ------------------------------------------------------------------ *
 * 1. 状态
 * ------------------------------------------------------------------ */

var state = {
  status: null, // kernel.status() / listVersions() 的公共部分
  items: [], // 本地快照
  latest: null, // checkLatest() 结果
  plugins: [],
  appStatus: null, // dsh:getStatus()
  busy: false,
  percent: 0,
  phase: '',
  running: false, // 是否有任务在跑（用于显示“进行中”）
  lastPhaseIndex: -1
}

var PHASES = ['resolve', 'stage', 'install', 'verify', 'smoke', 'promote', 'restart', 'done']
var PHASE_TEXT = {
  resolve: '查询版本',
  stage: '准备暂存目录',
  install: '下载依赖',
  verify: '校验文件',
  smoke: '冒烟测试',
  promote: '启用新内核',
  restart: '切换运行内核',
  done: '完成'
}

/* ------------------------------------------------------------------ *
 * 2. 遮罩：加载态 / 致命错误 / 重试
 * ------------------------------------------------------------------ */

var overlay = $('overlay')

function showOverlay(msg, detail, isError) {
  $('ovMsg').textContent = msg || '正在处理…'
  $('ovDetail').textContent = detail || ''
  overlay.classList.toggle('error', !!isError)
  overlay.classList.remove('hidden')
}

function hideOverlay() {
  overlay.classList.add('hidden')
}

function showFatal(msg, detail) {
  showOverlay(msg, detail, true)
}

/* ------------------------------------------------------------------ *
 * 3. 当前内核卡片
 * ------------------------------------------------------------------ */

function currentSnapshot() {
  var cur = state.status && state.status.currentVersion
  if (!cur) return null
  for (var i = 0; i < state.items.length; i++) {
    var it = state.items[i]
    if (!it) continue
    if (it.dirVersion === cur || it.version === cur) return it
  }
  return null
}

function renderCurrent() {
  var st = state.status || {}
  var snap = currentSnapshot()
  var cur = st.currentVersion || null

  $('curVersion').textContent = cur || '未安装'
  $('curVersion').className = cur ? 'ver' : 'ver none'

  var metaBits = []
  if (snap && snap.installedAt) metaBits.push('安装于 ' + formatTime(snap.installedAt))
  if (snap && snap.sizeBytes) metaBits.push(formatBytes(snap.sizeBytes))
  if (snap && snap.declaredEngines) metaBits.push('engines: node ' + snap.declaredEngines)
  $('curMeta').textContent = metaBits.length ? metaBits.join(' · ') : '本地快照信息不可用'

  // 徽章：只有 ready 才是绿的；其余一律红色并给出原因，避免“看着能选其实切不了”。
  var badge = $('curBadge')
  var badgeText = $('badgeText')
  var reason = $('badgeReason')
  badge.className = 'badge'
  if (!cur) {
    badge.classList.add('warn')
    badgeText.textContent = '未安装'
    reason.textContent = '尚未安装任何内核快照'
  } else if (!snap) {
    badge.classList.add('bad')
    badgeText.textContent = '快照缺失'
    reason.textContent = '当前版本 ' + cur + ' 在快照目录中不存在'
  } else if (snap.status === 'ready') {
    badge.classList.add('ok')
    badgeText.textContent = '兼容 · 可用'
    reason.textContent = '已通过入口校验与 Node 版本检查'
  } else {
    badge.classList.add('bad')
    badgeText.textContent = '不可用 · ' + statusLabel(snap.status)
    reason.textContent = snap.reason || '未提供原因'
  }

  // 字段区：每个字段都允许缺值，缺失显示 —，绝不假设字段存在。
  var fields = [
    ['当前版本', cur || '—', true],
    ['运行中版本', (st.runningVersion || '—'), true],
    ['内置 Node', st.nodeMajor ? 'v' + st.nodeMajor + '.x' : '—', true],
    ['内核模式', st.mode === 'pinned' ? '固定版本' : '自动（最新已启用）', false],
    ['固定版本', st.pinnedVersion || '—', true],
    ['保留快照数', st.keepSnapshots == null ? '—' : String(st.keepSnapshots), false],
    ['注册表', st.registry || '—', true]
  ]
  var box = $('curFields')
  box.textContent = ''
  for (var i = 0; i < fields.length; i++) {
    box.appendChild(fieldRow(fields[i][0], fields[i][1], fields[i][2]))
  }

  var paths = [
    ['快照目录', (st.snapshotsDir || '—'), st.snapshotsDir],
    ['DSH_HOME', ((state.appStatus && state.appStatus.dshHome) || '—'), (state.appStatus && state.appStatus.dshHome)]
  ]
  for (var j = 0; j < paths.length; j++) {
    box.appendChild(pathRow(paths[j][0], paths[j][1], paths[j][2]))
  }
}

function fieldRow(k, v, mono) {
  var d = document.createElement('div')
  d.className = 'field'
  var ke = document.createElement('span')
  ke.className = 'k'
  ke.textContent = k
  var ve = document.createElement('span')
  ve.className = mono ? 'v' : 'v muted'
  ve.textContent = v
  d.appendChild(ke)
  d.appendChild(ve)
  return d
}

/** 带“打开目录”按钮的路径行；openPath 由主进程自己校验，这里只传目标字符串。 */
function pathRow(k, v, target) {
  var d = document.createElement('div')
  d.className = 'field'
  var ke = document.createElement('span')
  ke.className = 'k'
  ke.textContent = k
  var ve = document.createElement('span')
  ve.className = 'v'
  ve.textContent = v
  d.appendChild(ke)
  d.appendChild(ve)
  if (target) {
    var btn = document.createElement('button')
    btn.textContent = '打开目录'
    btn.style.padding = '2px 8px'
    btn.style.fontSize = '11px'
    btn.addEventListener('click', function () {
      openPathSafe(target)
    })
    d.appendChild(btn)
  }
  return d
}

function openPathSafe(target) {
  if (!target || !api || typeof api.openPath !== 'function') return
  Promise.resolve()
    .then(function () {
      return api.openPath(target)
    })
    .catch(function (err) {
      setOpHint('打开目录失败：' + describeError(err), true)
    })
}

/* ------------------------------------------------------------------ *
 * 4. 版本选择 / 回滚选择
 * ------------------------------------------------------------------ */

function snapshotLabel(it) {
  var v = it.dirVersion || it.version || '?'
  if (it.version && it.dirVersion && it.version !== it.dirVersion) {
    return v + '（包版本 ' + it.version + '）'
  }
  return v
}

function isCurrent(it) {
  var cur = state.status && state.status.currentVersion
  return !!cur && (it.dirVersion === cur || it.version === cur)
}

function buildOption(it, suffix) {
  var opt = document.createElement('option')
  opt.value = it.dirVersion || it.version || ''
  var text = snapshotLabel(it) + (suffix || '')
  if (it.status !== 'ready') {
    // 禁用 + 写明原因：让用户在选择前就知道为什么不能选，
    // 而不是点了“切换”之后才收到一个 KERNEL_INVALID。
    text += ' — 不可选用：' + (it.reason || statusLabel(it.status))
  }
  opt.textContent = text
  opt.disabled = it.status !== 'ready'
  if (it.reason) opt.title = it.reason
  return opt
}

function renderVersionSelect() {
  var sel = $('versionSelect')
  sel.textContent = ''
  var readyCount = 0

  if (!state.items.length) {
    var o = document.createElement('option')
    o.textContent = '（本地无内核快照）'
    o.value = ''
    o.disabled = true
    sel.appendChild(o)
    sel.disabled = true
    $('btnSwitch').disabled = true
    return
  }

  sel.disabled = false
  for (var i = 0; i < state.items.length; i++) {
    var it = state.items[i]
    if (!it) continue
    if (it.status === 'ready') readyCount++
    sel.appendChild(buildOption(it, isCurrent(it) ? '（当前）' : ''))
  }

  // 默认选中当前版本；若当前版本不可用，则退到第一个 ready 快照。
  var cur = state.status && state.status.currentVersion
  var picked = false
  if (cur) {
    for (var j = 0; j < sel.options.length; j++) {
      var op = sel.options[j]
      if (op.value === cur && !op.disabled) {
        sel.value = cur
        picked = true
        break
      }
    }
  }
  if (!picked) {
    for (var k = 0; k < sel.options.length; k++) {
      if (!sel.options[k].disabled) {
        sel.selectedIndex = k
        break
      }
    }
  }
  $('btnSwitch').disabled = readyCount === 0 || !sel.value
}

function renderRollbackSelect() {
  var sel = $('rollbackSelect')
  sel.textContent = ''
  var cur = state.status && state.status.currentVersion
  var candidates = state.items.filter(function (it) {
    return it && it.status === 'ready' && it.dirVersion !== cur
  })

  if (!candidates.length) {
    var o = document.createElement('option')
    o.textContent = '（无可回滚的快照）'
    o.value = ''
    o.disabled = true
    sel.appendChild(o)
    sel.disabled = true
    $('btnRollback').disabled = true
    return
  }

  sel.disabled = false
  for (var i = 0; i < candidates.length; i++) {
    sel.appendChild(buildOption(candidates[i], ''))
  }
  $('btnRollback').disabled = false
}

/* ------------------------------------------------------------------ *
 * 5. 检查更新
 * ------------------------------------------------------------------ */

function setUpdateHint(text, kind) {
  var el = $('updateHint')
  el.textContent = text || ''
  el.className = 'hint' + (kind ? ' ' + kind : '')
}

function checkLatest() {
  if (!api || !api.kernel) return
  var btn = $('btnCheck')
  btn.disabled = true
  setUpdateHint('正在查询远端最新版本…', '')

  return Promise.resolve()
    .then(function () {
      return api.kernel.checkLatest()
    })
    .then(function (res) {
      state.latest = res || null
      $('btnUpdate').style.display = 'none'

      // 离线时返回 { latest: null, error }；绝不能把它当成“已是最新”，
      // 否则用户会以为自己用的是最新版。
      if (!res || res.error || !res.latest) {
        var errText = (res && res.error) || '未获取到版本信息'
        setUpdateHint(
          '检查失败：' + errText + '。当前内核仍为 ' + ((res && res.current) || '未知') + '，可正常使用。',
          'err'
        )
        return
      }

      var cur = (res.current || (state.status && state.status.currentVersion) || '未知')
      if (res.outdated) {
        setUpdateHint('发现新版本 ' + res.latest + '，当前为 ' + cur + '。', 'ok')
        var b = $('btnUpdate')
        b.textContent = '更新到 ' + res.latest
        b.style.display = ''
        b.disabled = false
      } else {
        setUpdateHint('已是最新（' + res.latest + '），无需更新。', '')
      }
    })
    .catch(function (err) {
      setUpdateHint('检查失败：' + describeError(err) + ' ' + busyHint(describeError(err)), 'err')
    })
    .then(function () {
      btn.disabled = false
    })
}

/* ------------------------------------------------------------------ *
 * 6. 通用任务包装：busy 期间禁用按钮，任何异常都落到界面上
 * ------------------------------------------------------------------ */

function setBusy(on) {
  state.busy = !!on
  var ids = ['btnSwitch', 'btnRollback', 'btnPrune', 'btnRestart', 'btnUpdate', 'btnCheck', 'btnInstall']
  for (var i = 0; i < ids.length; i++) {
    var el = $(ids[i])
    if (!el) continue
    // 保留原本因为“没有可选项”而禁用的状态，任务结束后由 render 重新计算。
    if (on) {
      el.dataset.wasDisabled = el.disabled ? '1' : ''
      el.disabled = true
    } else if (el.dataset.wasDisabled !== '1') {
      el.disabled = false
    }
  }
}

function setOpHint(text, isErr) {
  var el = $('opHint')
  el.textContent = text || ''
  el.className = 'hint' + (isErr ? ' err' : '')
}

/**
 * 所有 IPC 都可能 reject（离线 / UPDATE_BUSY / 版本不兼容）。
 * 统一在这里兜住，保证不会有人留在 loading 状态。
 */
function runTask(label, fn) {
  if (state.busy) {
    setOpHint('有任务正在执行，请稍后再试。', true)
    return Promise.resolve()
  }
  setBusy(true)
  resetProgress()
  setPhase('stage', label || '正在处理…')
  $('progressState').textContent = '进行中'
  setOpHint(label || '', false)

  return Promise.resolve()
    .then(fn)
    .then(function (res) {
      setOpHint((label || '操作') + '完成。', false)
      return res
    })
    .catch(function (err) {
      var msg = describeError(err)
      markFailed(msg)
      setOpHint((label || '操作') + '失败：' + msg + ' ' + busyHint(msg), true)
      return null
    })
    .then(function (res) {
      setBusy(false)
      $('progressState').textContent = '空闲'
      // 无论成功失败都刷新一次：失败时要证明“当前内核没变”。
      return refresh(true).then(function () {
        return res
      })
    })
}

/* ------------------------------------------------------------------ *
 * 7. 进度区
 * ------------------------------------------------------------------ */

var MAX_LINES = 300
var pendingLine = ''
var consoleEl = $('console')
var consoleIdle = true

function renderStages() {
  var box = $('stages')
  box.textContent = ''
  var curIdx = PHASES.indexOf(state.phase)
  for (var i = 0; i < PHASES.length; i++) {
    var p = PHASES[i]
    var el = document.createElement('span')
    el.className = 'stage'
    if (state.phase === 'failed') {
      // failed 不对应管道中的某一步，只把已完成的部分标绿。
      if (i <= state.lastPhaseIndex) el.classList.add('done')
    } else if (curIdx >= 0) {
      if (i < curIdx) el.classList.add('done')
      else if (i === curIdx) el.classList.add('active')
    }
    el.textContent = PHASE_TEXT[p] || p
    box.appendChild(el)
  }
  if (state.phase === 'failed') {
    var f = document.createElement('span')
    f.className = 'stage failed'
    f.textContent = '失败'
    box.appendChild(f)
  }
}

function setPercent(pct) {
  var v = clamp(Number(pct) || 0, 0, 100)
  state.percent = v
  $('barFill').style.width = v + '%'
}

function setPhase(phase, label) {
  if (typeof phase === 'string' && phase) {
    state.phase = phase
    var idx = PHASES.indexOf(phase)
    if (idx >= 0) state.lastPhaseIndex = idx
  }
  renderStages()
  if (label) $('progressState').textContent = String(label)
}

function resetProgress() {
  state.percent = 0
  state.phase = ''
  state.lastPhaseIndex = -1
  pendingLine = ''
  setPercent(0)
  $('bar').className = 'bar'
  $('failBox').classList.remove('show')
  consoleEl.textContent = ''
  consoleIdle = true
  var idle = document.createElement('span')
  idle.className = 'idle'
  idle.textContent = '等待输出…'
  consoleEl.appendChild(idle)
  renderStages()
  $('progressState').textContent = '空闲'
}

function ensureConsoleReady() {
  if (consoleIdle) {
    consoleEl.textContent = ''
    consoleIdle = false
  }
}

function pushLine(text) {
  ensureConsoleReady()
  var line = document.createElement('div')
  line.textContent = text
  consoleEl.appendChild(line)
  while (consoleEl.childElementCount > MAX_LINES) {
    consoleEl.removeChild(consoleEl.firstChild)
  }
  // 用户手动往上翻时不打扰他，否则始终贴底。
  if (consoleEl.scrollHeight - consoleEl.scrollTop - consoleEl.clientHeight < 60) {
    consoleEl.scrollTop = consoleEl.scrollHeight
  }
}

/** install 阶段持续吐 output，可能不含换行，先攒到出现换行为止。 */
function appendOutput(text) {
  pendingLine += text
  var parts = pendingLine.split('\n')
  pendingLine = parts.pop() || ''
  for (var i = 0; i < parts.length; i++) {
    pushLine(parts[i])
  }
}

function flushPending() {
  if (pendingLine) {
    var t = pendingLine
    pendingLine = ''
    pushLine(t)
  }
}

function markFailed(message) {
  flushPending()
  state.phase = 'failed'
  setPercent(100)
  $('bar').className = 'bar fail'
  $('failMsg').textContent = message || '未提供错误信息'
  // 这里必须明确说出来：内核下载到暂存目录 + 冒烟通过才 promote，
  // 因此走到 failed 时 currentVersion 指针从未被改写。
  $('failSafe').textContent =
    '当前内核未发生变化：新内核在 promote 之前失败，暂存目录会被自动清理，正在运行的内核仍是 ' +
    ((state.status && (state.status.runningVersion || state.status.currentVersion)) || '原版本') +
    '。'
  $('failBox').classList.add('show')
  renderStages()
  $('progressState').textContent = '失败'
}

function markDone(message) {
  flushPending()
  state.phase = 'done'
  state.lastPhaseIndex = PHASES.indexOf('done')
  setPercent(100)
  $('bar').className = 'bar done'
  renderStages()
  $('progressState').textContent = message || '完成'
}

/** onProgress 回调：字段全部可选，逐项兜底。 */
function onProgress(p) {
  if (!p || typeof p !== 'object') return
  if (typeof p.output === 'string' && p.output) appendOutput(p.output)
  if (typeof p.percent === 'number' && isFinite(p.percent)) setPercent(p.percent)
  if (typeof p.phase === 'string' && p.phase) {
    if (p.phase === 'failed') {
      markFailed(p.message || p.label || '任务失败')
      return
    }
    if (p.phase === 'done') {
      markDone(p.label || '完成')
      if (p.message) pushLine(p.message)
    } else {
      setPhase(p.phase, p.label || '')
    }
  } else if (typeof p.label === 'string' && p.label) {
    // 插件安装只发 { phase:'stage', label }，没有 percent。
    $('progressState').textContent = p.label
  }
  if (typeof p.message === 'string' && p.message && p.phase !== 'done') {
    pushLine(p.message)
  }
}

/* ------------------------------------------------------------------ *
 * 8. 限速
 * ------------------------------------------------------------------ */

function limitValue(el) {
  var n = Number(el.value)
  if (!isFinite(n) || n < 0) return 0
  return Math.round(n)
}

function renderLimitUI(kernelKBps, pluginKBps) {
  var kv = Number(kernelKBps) || 0
  var pv = Number(pluginKBps) || 0
  $('kernelNum').value = String(kv)
  $('pluginNum').value = String(pv)
  $('kernelRange').value = String(clamp(kv, 0, 4096))
  $('pluginRange').value = String(clamp(pv, 0, 4096))
  updateLimitLabels()
}

function updateLimitLabels() {
  var kv = limitValue($('kernelNum'))
  var pv = limitValue($('pluginNum'))
  $('kernelLimitVal').textContent = kv > 0 ? kv + ' KB/s' : '0 KB/s（不限速）'
  $('pluginLimitVal').textContent = pv > 0 ? pv + ' KB/s' : '0 KB/s（不限速）'
}

var limitTimer = null
function scheduleApplyLimits() {
  updateLimitLabels()
  if (limitTimer) clearTimeout(limitTimer)
  limitTimer = setTimeout(function () {
    limitTimer = null
    applyLimits()
  }, 600)
}

function applyLimits() {
  if (!api || !api.kernel || typeof api.kernel.setLimits !== 'function') return
  var payload = {
    kernelKBps: limitValue($('kernelNum')),
    pluginKBps: limitValue($('pluginNum'))
  }
  return Promise.resolve()
    .then(function () {
      return api.kernel.setLimits(payload)
    })
    .then(function (res) {
      if (res && res.limits) {
        renderLimitUI(res.limits.kernelKBps, res.limits.pluginKBps)
      }
      var hint = $('limitHint')
      hint.className = 'hint ok'
      hint.textContent =
        '已保存：内核 ' + payload.kernelKBps + ' KB/s，插件 ' + payload.pluginKBps + ' KB/s（0 为不限速）。'
    })
    .catch(function (err) {
      var hint = $('limitHint')
      hint.className = 'hint err'
      hint.textContent = '限速保存失败：' + describeError(err)
    })
}

function bindLimitControls(rangeId, numId) {
  var range = $(rangeId)
  var num = $(numId)
  range.addEventListener('input', function () {
    num.value = range.value
    scheduleApplyLimits()
  })
  num.addEventListener('input', function () {
    var v = limitValue(num)
    range.value = String(clamp(v, 0, 4096))
    scheduleApplyLimits()
  })
}

/* ------------------------------------------------------------------ *
 * 9. 插件
 * ------------------------------------------------------------------ */

function setPluginHint(text, isErr) {
  var el = $('pluginHint')
  el.textContent = text || ''
  el.className = 'hint' + (isErr ? ' err' : '')
}

function renderPlugins() {
  var tbody = $('pluginRows')
  tbody.textContent = ''
  var list = state.plugins || []
  $('pluginEmpty').style.display = list.length ? 'none' : 'block'

  for (var i = 0; i < list.length; i++) {
    tbody.appendChild(pluginRow(list[i]))
  }
}

function pluginRow(p) {
  p = p || {}
  var tr = document.createElement('tr')

  // 名称列
  var tdName = document.createElement('td')
  if (p.builtin) {
    var tag = document.createElement('span')
    tag.className = 'tag builtin'
    // 内置插件（backup-roll）承担内核管理本身，删掉它等于删掉自救能力。
    tag.textContent = '内置 · 不可卸载'
    tdName.appendChild(tag)
  }
  var nm = document.createElement('div')
  nm.textContent = p.name || p.id || '未命名插件'
  tdName.appendChild(nm)
  var idLine = document.createElement('div')
  idLine.style.color = 'var(--dim)'
  idLine.style.fontSize = '11.5px'
  idLine.textContent = p.id || ''
  tdName.appendChild(idLine)
  if (p.description) {
    var desc = document.createElement('div')
    desc.style.color = 'var(--muted)'
    desc.style.fontSize = '11.5px'
    desc.textContent = p.description
    tdName.appendChild(desc)
  }
  tr.appendChild(tdName)

  var tdVer = document.createElement('td')
  tdVer.className = 'mono'
  tdVer.textContent = p.version || '—'
  tr.appendChild(tdVer)

  var tdTime = document.createElement('td')
  tdTime.className = 'mono'
  tdTime.textContent = formatTime(p.updatedAt)
  tr.appendChild(tdTime)

  // 启用开关
  var tdState = document.createElement('td')
  var toggle = document.createElement('button')
  toggle.textContent = p.enabled === false ? '已禁用' : '已启用'
  if (p.enabled === false) toggle.style.color = 'var(--dim)'
  toggle.disabled = !!p.builtin // 内置插件不允许禁用，否则内核管理界面会自我关闭
  toggle.addEventListener('click', function () {
    var next = p.enabled === false
    Promise.resolve()
      .then(function () {
        return api.plugins.setEnabled(p.id, next)
      })
      .then(function () {
        setPluginHint('已' + (next ? '启用' : '禁用') + '插件 ' + p.id + '。', false)
        return loadPlugins()
      })
      .catch(function (err) {
        setPluginHint('操作失败：' + describeError(err), true)
      })
  })
  tdState.appendChild(toggle)
  tr.appendChild(tdState)

  // 卸载
  var tdOps = document.createElement('td')
  var del = document.createElement('button')
  del.className = 'danger'
  del.textContent = '卸载'
  del.disabled = !!p.builtin
  if (p.builtin) del.title = '内置插件不可卸载'
  del.addEventListener('click', function () {
    if (!window.confirm('确认卸载插件 ' + p.id + '？')) return
    runTask('卸载插件 ' + p.id, function () {
      return api.plugins.uninstall(p.id).then(function (res) {
        if (res && Array.isArray(res.plugins)) state.plugins = res.plugins
        renderPlugins()
        return res
      })
    })
  })
  tdOps.appendChild(del)
  tr.appendChild(tdOps)

  return tr
}

function loadPlugins() {
  if (!api || !api.plugins) return Promise.resolve()
  return Promise.resolve()
    .then(function () {
      return api.plugins.list()
    })
    .then(function (res) {
      state.plugins = (res && Array.isArray(res.plugins) && res.plugins) || []
      renderPlugins()
      setPluginHint('', false)
    })
    .catch(function (err) {
      // 插件读取失败不该连累内核区块，只在插件区提示。
      setPluginHint('插件列表读取失败：' + describeError(err), true)
    })
}

/* ------------------------------------------------------------------ *
 * 10. 载入与刷新
 * ------------------------------------------------------------------ */

function refresh(silent) {
  if (!api || !api.kernel) {
    showFatal('未检测到 window.dshDesktop', '当前页面不是通过应用主窗口加载的，preload 未注入。')
    return Promise.resolve()
  }
  if (!silent) {
    showOverlay('正在读取内核状态…', '', false)
    $('secCurrent').classList.add('is-loading')
  }

  // listVersions 是唯一的关键数据；失败则整页进入可重试的错误态。
  return Promise.resolve()
    .then(function () {
      return api.kernel.listVersions()
    })
    .then(function (versions) {
      versions = versions || {}
      state.status = versions
      state.items = Array.isArray(versions.items) ? versions.items.filter(Boolean) : []
      renderCurrent()
      renderVersionSelect()
      renderRollbackSelect()
      renderLimitUI(
        versions.limits ? versions.limits.kernelKBps : 0,
        versions.limits ? versions.limits.pluginKBps : 0
      )
      $('keepInput').value = String(versions.keepSnapshots || 3)
      $('secCurrent').classList.remove('is-loading')
      hideOverlay()
    })
    .catch(function (err) {
      $('secCurrent').classList.remove('is-loading')
      showFatal('无法读取内核状态', describeError(err))
      return null
    })
    .then(function () {
      // 以下两项是补充信息，失败只影响各自区域。
      return Promise.all([loadPlugins(), loadAppStatus()])
    })
    .then(function () {
      renderCurrent()
    })
}

function loadAppStatus() {
  if (!api || typeof api.getStatus !== 'function') return Promise.resolve()
  return Promise.resolve()
    .then(function () {
      return api.getStatus()
    })
    .then(function (s) {
      state.appStatus = s || null
    })
    .catch(function () {
      state.appStatus = null
    })
}

/* ------------------------------------------------------------------ *
 * 11. 事件绑定
 * ------------------------------------------------------------------ */

function selectedVersion(selId) {
  var sel = $(selId)
  if (!sel) return null
  var v = sel.value
  // 兜底：个别情况下 select.value 尚未同步，退回到当前选中的 option。
  if (!v && sel.options && sel.selectedIndex >= 0) {
    var cur = sel.options[sel.selectedIndex]
    if (cur) v = cur.value
  }
  if (!v) return null
  if (sel.selectedIndex >= 0) {
    var op = sel.options[sel.selectedIndex]
    if (op && op.disabled) return null // 兜底：禁用项即便被选中也不允许提交
  }
  return v
}

function bindEvents() {
  $('btnCheck').addEventListener('click', function () {
    checkLatest()
  })

  $('btnUpdate').addEventListener('click', function () {
    runTask('下载并启用新内核', function () {
      return api.kernel.update('latest', true)
    })
  })

  $('btnSwitch').addEventListener('click', function () {
    var v = selectedVersion('versionSelect')
    if (!v) {
      setOpHint('请选择一个可用的（ready）快照。', true)
      return
    }
    runTask('切换到 ' + v, function () {
      return api.kernel.switchVersion(v)
    })
  })

  $('btnRollback').addEventListener('click', function () {
    var v = selectedVersion('rollbackSelect')
    if (!v) {
      setOpHint('没有其他可用快照可供回滚。', true)
      return
    }
    runTask('回滚到 ' + v, function () {
      return api.kernel.rollback(v)
    })
  })

  $('btnPrune').addEventListener('click', function () {
    var keep = Number($('keepInput').value)
    if (!isFinite(keep) || keep < 1) keep = 1
    keep = Math.round(keep)
    if (!window.confirm('将保留最近 ' + keep + ' 个快照，其余旧快照会被删除。继续？')) return
    runTask('清理旧快照（保留 ' + keep + ' 个）', function () {
      return api.kernel.prune(keep).then(function (res) {
        var kept = (res && res.kept && res.kept.length) || 0
        var retired = (res && res.retired && res.retired.length) || 0
        pushLine('已保留 ' + kept + ' 个快照，清理 ' + retired + ' 个。')
        if (res && Array.isArray(res.retired) && res.retired.length) {
          for (var i = 0; i < res.retired.length; i++) pushLine('  移除：' + res.retired[i])
        }
        return res
      })
    })
  })

  $('btnRestart').addEventListener('click', function () {
    runTask('重启 dsh 运行时', function () {
      return api.restart()
    })
  })

  $('btnInstall').addEventListener('click', function () {
    var name = ($('pluginName').value || '').trim()
    var version = ($('pluginVersion').value || '').trim() || 'latest'
    if (!name) {
      setPluginHint('请填写插件包名。', true)
      return
    }
    runTask('安装插件 ' + name, function () {
      return api.plugins.install(name, version).then(function (res) {
        if (res && Array.isArray(res.plugins)) {
          state.plugins = res.plugins
          renderPlugins()
        }
        $('pluginName').value = ''
        $('pluginVersion').value = ''
        return res
      })
    })
  })

  bindLimitControls('kernelRange', 'kernelNum')
  bindLimitControls('pluginRange', 'pluginNum')

  $('btnRetry').addEventListener('click', function () {
    refresh(false)
  })
  $('btnOpenData').addEventListener('click', function () {
    openPathSafe((state.appStatus && state.appStatus.userData) || '')
  })

  // 内核进程状态变化（starting / ready / error）时同步“运行中版本”。
  if (api && typeof api.onStatus === 'function') {
    try {
      api.onStatus(function (s) {
        if (!s) return
        if (s && (s.kernel || s.state === 'ready')) {
          loadAppStatus().then(function () {
            renderCurrent()
          })
        }
      })
    } catch (err) {
      /* 订阅失败不影响主流程 */
    }
  }

  // 最后一道防线：任何漏网的 rejection 都显示出来，绝不让页面静默卡住。
  window.addEventListener('unhandledrejection', function (ev) {
    var reason = ev && ev.reason
    pushLine('未处理的异常：' + describeError(reason))
    if (state.busy) {
      markFailed(describeError(reason))
      setBusy(false)
    }
  })
  window.addEventListener('error', function (ev) {
    pushLine('脚本错误：' + ((ev && ev.message) || '未知'))
  })
}

/* ------------------------------------------------------------------ *
 * 12. 启动
 * ------------------------------------------------------------------ */

function boot() {
  if (!api || !api.kernel) {
    showFatal(
      '未检测到内核管理接口',
      'window.dshDesktop.kernel 不存在。请确认该页面由应用主窗口加载，且 preload 已启用。'
    )
    return
  }

  if (typeof api.kernel.onProgress === 'function') {
    try {
      api.kernel.onProgress(onProgress)
    } catch (err) {
      /* 订阅失败只影响进度显示 */
    }
  }

  bindEvents()
  renderStages()
  resetProgress()
  refresh(false)
}

boot()
